    pattern = r'File: ' + re.escape(file_path) + r'\n={2,}\n(.*?)(?=\n={2,}\nFile:|\Z)'
    match = re.search(pattern, content, re.DOTALL)
    if match:
        return match.group(1)
    return None

def search_for_encoding_related_code(content, file_paths, keywords):
    results = {}
    for file_path in file_paths:
        file_content = extract_file_content(content, file_path)
