            for keyword in keywords:
                if keyword in file_content.lower():
                    if file_path not in results:
                        results[file_path] = []
                    if keyword not in results[file_path]:
                        results[file_path].append(keyword)
    return results

encoding_keywords = ['encode', 'unicode', 'utf', 'charmap', 'write', 'fix', 'open']
encoding_related_files = search_for_encoding_related_code(content, potential_files, encoding_keywords)
