def find_in_content(content, search_pattern, context_lines=5):
    """Find pattern matches in content with context lines."""
    for match in re.finditer(search_pattern, content, re.DOTALL):
        start = max(0, content.rfind('\n', 0, match.start()) - context_lines * 80)
        end = min(len(content), content.find('\n', match.end()) + context_lines * 80)
        yield content[start:end]

# Search for file writing and encoding-related code in linted_file.py
encoding_patterns = [
    r'def\s+write\s*\([^{]*',
    r'encoding\s*=',
    r'open\([^)]*encoding',
    r'charmap'
]

for pattern in encoding_patterns:
    print(f"\nSearching for pattern: {pattern}")
    results = list(find_in_content(content, pattern))
    if results:
        for i, result in enumerate(results[:2]):  # Limit to first 2 results to avoid verbosity
            print(f"Result {i+1}:")
            print(result[:300])  # Print first 300 chars
            print("...")
